import{_ as n,C as o,o as s,c as b,a5 as t,j as r,a as e,E as i}from"./chunks/framework.CnBNXlt7.js";const k=JSON.parse('{"title":"安徽","description":"","frontmatter":{},"headers":[],"relativePath":"trip/china/anhui/index.md","filePath":"trip/china/anhui/index.md","lastUpdated":1752159604000}'),d={name:"trip/china/anhui/index.md"};function p(u,a,h,m,x,q){const l=o("Badge");return s(),b("div",null,[a[10]||(a[10]=t('<h1 id="安徽" tabindex="-1">安徽 <a class="header-anchor" href="#安徽" aria-label="Permalink to &quot;安徽&quot;">​</a></h1><p>玩遍安徽路线（双城记/三城记）</p><ul><li>宣城、芜湖、马鞍山</li></ul><h2 id="合肥" tabindex="-1">合肥 <a class="header-anchor" href="#合肥" aria-label="Permalink to &quot;合肥&quot;">​</a></h2><h2 id="芜湖" tabindex="-1">芜湖 <a class="header-anchor" href="#芜湖" aria-label="Permalink to &quot;芜湖&quot;">​</a></h2><h3 id="美食" tabindex="-1">美食 <a class="header-anchor" href="#美食" aria-label="Permalink to &quot;美食&quot;">​</a></h3><p>渣肉蒸饭：上面是粉蒸肉和豆皮，下边是米饭，应该去现场吃更好吃<br> 稻香米拌饭：（跟米村差不多味道）<br> 卡旺卡：真的可以！小料免费加，品种特别多！选择性大！这个可以试一试<br> 百年耿记老店：小笼汤包、虾籽面<br> 小金蒸饭：蒸饭、豆腐脑<br> 申元街麻辣烫：麻辣烫<br> 小戴烤鸭：红皮鸭子、烤鸭<br> 二姐红豆：赤豆酒酿、红豆双皮奶<br> 芜湖良麦：冰豆腐花、桂花酒酿豆乳</p><h3 id="游玩" tabindex="-1">游玩 <a class="header-anchor" href="#游玩" aria-label="Permalink to &quot;游玩&quot;">​</a></h3><p>赭山公园<br> 老海关钟楼，之后沿着【长江】一直走<br> 天主堂/英驻芜领馆旧址<br> 雨耕山<br> 中江塔，中山路步行街<br> 鸠兹景区<br> 芜湖古城<br> 罗兰小镇</p><h2 id="马鞍山" tabindex="-1">马鞍山 <a class="header-anchor" href="#马鞍山" aria-label="Permalink to &quot;马鞍山&quot;">​</a></h2><ul><li>雨山湖公园</li><li>马鞍山市博物馆</li><li>采石矶风景区</li><li>长江不夜城</li></ul><p>一日游：雨山湖公园、马鞍山市博物馆、采石矶风景区、长江不夜城</p><div class="warning custom-block"><p class="custom-block-title">采石矶风景区</p><p>采石矶景区东门，门口扫码购票，想要纸质票，得去北门买</p><p>景区内主要打卡点：<br> 延园 林散之艺术馆 谪仙园（这里面遇到一群猫猫，喂猫占用了不少时间）太白楼 李白纪念馆 李白衣冠冢 广济寺 三元洞 三台阁 沿江栈道 （三台阁16:30关门，想登楼观景的一定要注意时间）<br> 从三台阁下山，依旧东门出。</p><p>采石矶东门出来就是长江不夜城</p></div><p>Day1: 翠林水城→雨山湖公园→金鹰<br> Day2: 采石矶→长江不夜城→师专夜市</p><p>翠林水城 洗浴中心 可无限吃</p><p>詹记桃酥，弥森</p><h2 id="宣城" tabindex="-1">宣城 <a class="header-anchor" href="#宣城" aria-label="Permalink to &quot;宣城&quot;">​</a></h2><h3 id="美食-1" tabindex="-1">美食 <a class="header-anchor" href="#美食-1" aria-label="Permalink to &quot;美食&quot;">​</a></h3><details class="details custom-block"><summary>—— by (xhs)网友</summary><p>吃饭，第一天午餐在宣城城区吃小吃，面条、麻辣粉丝、粑粑、什么的比较不错。网上写的什么阁什么阁的，什么锅的都是营销，炸弹，你懂的。晚上去泾县安排好住宿慢慢找苍蝇馆子，泾县的土菜烧的比宣城城区好多了，而且食材也好。</p><p>魏氏泡泡混沌很好吃的，金龙发面饺子也不错，土生土长的宣城人</p><p>蜀渝里冒菜(锦城南路店)<br> 夏炉一头牛烤肉<br> 丁师傅205老面馆<br> 金龙饺子店<br> 陈记宁国眼镜胖子粑粑（春归苑店）<br> 老字号魏氏馄饨馆<br> 丁氏粉丝<br> 滕师傅桂花糕<br> 黄毛面馆(西园路店)</p></details><h3 id="游玩-1" tabindex="-1">游玩 <a class="header-anchor" href="#游玩-1" aria-label="Permalink to &quot;游玩&quot;">​</a></h3>',20)),r("p",null,[a[0]||(a[0]=e("看起来需要自驾，除了敬亭山",-1)),i(l,{type:"danger",text:"自驾提醒"})]),r("ul",null,[a[2]||(a[2]=r("li",null,"查济古村",-1)),r("li",null,[a[1]||(a[1]=e("徽杭古道，6h+，",-1)),i(l,{type:"danger",text:"徒步玩家"})]),a[3]||(a[3]=r("li",null,"月亮湾",-1)),a[4]||(a[4]=r("li",null,"龙川景区，2h",-1)),a[5]||(a[5]=r("li",null,"敬亭山",-1)),a[6]||(a[6]=r("li",null,"江村",-1)),a[7]||(a[7]=r("li",null,"桃花潭",-1)),a[8]||(a[8]=r("li",null,"水墨汀溪",-1)),a[9]||(a[9]=r("li",null,"宣纸博物馆",-1))]),a[11]||(a[11]=t('<div class="warning custom-block"><p class="custom-block-title">敬亭山游玩</p><p><strong>休闲版</strong><br> 打车或自驾 直接到【敬亭山售票处】上山和下山都乘坐观光车<br> 核心景点都不会错过: 太白独坐楼+敬亭之巅+天际阁<br> 沿着红色坡道走，不爬台阶但也足够刺激废腿<br> 旅游高峰日尽量时间上错峰出游，否则观光车也要排队很久，每辆车载客量不多<br> 3-4小时游玩</p><p><strong>挑战版</strong><br> 东广场【敬亭山】牌坊出发，全程步行上山下山12km+<br> 走台阶路，除了核心景点，还能看到相思泉、玉真公主像等小景点<br> 下山回程可以走一走山下小村庄，路边全是各种诗词<br> 深度品味敬亭山，游玩时间预留5小时</p></div><h2 id="黄山" tabindex="-1">黄山 <a class="header-anchor" href="#黄山" aria-label="Permalink to &quot;黄山&quot;">​</a></h2><p>⛰️爬山看景：黄山风景区、齐云山<br> 🏡人文景观：棠樾牌坊、中国徽州文化博物馆<br> 🚏城市漫步：徽州古城、屯溪老街<br> 🏠著名古村：宏村、西递、呈坎、西溪南古村落、塔川<br> 🏠小众古村：南屏、屏山村、碧山村、卢村、阳产土楼、卖花渔村、木梨硔<br> 🌳自然景观：木坑竹海、太平湖风景区、打鼓岭、灵山梯田油菜花、新安江山水画廊<br> 🍱特色美食：臭鳜鱼、毛豆腐、一品锅、黄山烧饼、蕨菜炒腊肉、灵山酒酿、永春土菜馆、吴厨徽菜楼</p>',3))])}const P=n(d,[["render",p]]);export{k as __pageData,P as default};
